def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.75
        return max(0.0, min(budget, safe_bid))

    est_demand_units = 1
    for oid, opp in alive:
        req = opp.get('water_requirement', WATER_REQ)
        if req <= supply:
            est_demand_units += 1
    tightness = est_demand_units / max(1.0, supply / float(WATER_REQ))

    bob_prev = None
    cindy_prev = None
    highest_prev = 0.0
    urgent_opp = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = 0.0
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid', 0.0))
            if bid > highest_prev:
                highest_prev = bid
        if oid == 'Bob':
            bob_prev = bid
        if oid == 'Cindy':
            cindy_prev = bid
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1

    if bob_prev is None:
        bob_prev = 75.5
    if cindy_prev is None:
        cindy_prev = 142.5

    pressure_bid = bob_prev + 1.6
    if urgent_opp >= 1:
        pressure_bid += 2.0
    if tightness > 1.8:
        pressure_bid += 3.0

    if hp <= 2 or no_water_days >= 1:
        bid = max(pressure_bid, DAILY_SALARY * 0.92)
    elif hp <= 4:
        bid = max(pressure_bid, DAILY_SALARY * 0.78)
    else:
        if supply >= 22 and tightness < 1.3:
            bid = DAILY_SALARY * 0.34
        elif supply >= 19 and highest_prev >= 100:
            bid = max(DAILY_SALARY * 0.48, bob_prev + 0.8)
        elif supply <= 17:
            bid = max(pressure_bid, DAILY_SALARY * 0.82)
        else:
            bid = max(DAILY_SALARY * 0.56, bob_prev + 0.9)

    if cindy_prev > 120 and hp > 4 and no_water_days == 0 and supply >= 19:
        bid = min(bid, bob_prev + 0.9)

    reserve = 0.0
    if hp > 4:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.6
    max_spend = max(0.0, budget - reserve)

    if hp <= 2 or no_water_days >= 1:
        max_spend = budget

    bid = min(bid, max_spend if max_spend > 0 else budget)
    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents and inspect yesterday bids only
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents are alive, bid conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate whether there is a strong bidding pressure (e.g., Cindy)
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Budget and HP heuristics
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Determine target bid: small edge over likely clearing price if pressure is high
    # But avoid overpaying since Cindy already spent huge and may be trying to lock supply.
    # If highest_prev_bid is very large, we try to undercut rather than match.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        # Underbid strategy: bid around a fraction of daily salary, but enough to compete.
        # Use second_prev_bid as a weak proxy for clearing.
        base = max(DAILY_SALARY * 0.35, second_prev_bid * 0.55)
        if hp <= 2:
            base *= 1.6
        elif hp <= 4:
            base *= 1.25
        # Also consider supply: if supply is near minimum, be slightly more aggressive.
        if supply <= float(MIN_SUPPLY) + 1.0:
            base *= 1.15
    elif highest_prev_bid >= DAILY_SALARY * 0.7:
        # Moderate pressure: bid near half daily salary or slightly above second-highest
        base = max(DAILY_SALARY * 0.5, second_prev_bid * 0.75)
        if hp <= 2:
            base *= 1.4
        elif hp <= 4:
            base *= 1.15
    else:
        # Low pressure: bid enough to ensure water without wasting budget
        base = DAILY_SALARY * 0.55
        if hp <= 2:
            base = DAILY_SALARY * 0.85
        elif hp <= 4:
            base = DAILY_SALARY * 0.7
        # If supply is low, increase slightly
        if supply <= float(MIN_SUPPLY) + 1.0:
            base *= 1.1

    # Convert base to a safe bid within budget; keep it integer-like but not required
    bid = float(min(budget, base))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

